macos-remaining-tests:
  name: macOS remaining tests (${{ matrix.shard }}/2)
  if: ${{ !cancelled() && needs.scope.result == 'success' && needs.scope.outputs.full == 'true' && needs.macos-remaining-build.result == 'success' }}
  needs: [scope, macos-remaining-build]
  runs-on: macos-latest
  timeout-minutes: 90
  strategy:
    fail-fast: false
    matrix:
      shard: [1, 2]
  env:
    CARGO_INCREMENTAL: '0'
  steps:
    - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
      with:
        fetch-depth: 2
    - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1
      with:
        node-version: 22
    - uses: dtolnay/rust-toolchain@stable
      with:
        toolchain: ${{ needs.macos-remaining-build.outputs.rustVersion }}
    - uses: taiki-e/install-action@v2.88.1
      with:
        tool: cargo-nextest@0.9.150
        fallback: none
    - uses: actions/download-artifact@v8
      with:
        name: macos-remaining-binaries-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
        path: ${{ runner.temp }}/macos-remaining-archive
    - uses: actions/download-artifact@v8
      with:
        name: macos-remaining-metadata-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
        path: ${{ runner.temp }}/macos-remaining-archive
    - name: Execute validated four-worker partition
      env:
        CARGO_BUILD_JOBS: '2'
        RUST_TEST_THREADS: '4'
        MANIFEST_SHA: ${{ needs.macos-remaining-build.outputs.manifestSha256 }}
        ARCHIVE_SHA: ${{ needs.macos-remaining-build.outputs.archiveSha256 }}
        SHARD: ${{ matrix.shard }}
      run: node scripts/ci/windows-coverage.mjs consume-macos-remaining "$SHARD" "$RUNNER_TEMP/macos-remaining-archive" "$RUNNER_TEMP/macos-remaining-results" "$MANIFEST_SHA" "$ARCHIVE_SHA"
    - name: Preserve receipts and raw execution diagnostics
      if: ${{ always() }}
      uses: actions/upload-artifact@v7
      with:
        name: macos-remaining-results-${{ matrix.shard }}-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
        path: ${{ runner.temp }}/macos-remaining-results/
        retention-days: 14
        if-no-files-found: ${{ job.status == 'success' && 'error' || 'ignore' }}

