                if admission
                    .with_runtime(|runtime| {
                        if let Some(path) =
                            crate::config_store::account_path(&base_dir, &account_id, "trust.json")
                        {
                            runtime.handle().replace_verified_dm_pull_peers(
                                crate::trust::verified_fingerprints_at(&path),
                            );
